admin_desk='''function AdminDesk({onWechatIncoming,onCopyMaterial,hasMaterial}:{onWechatIncoming?:()=>void;onCopyMaterial?:(m:SharedMaterial)=>void;hasMaterial?:(id:string)=>boolean}){\n const [tab,setTab]=useState<"watch"|"users"|"ops"|"recycle">(()=>adminDeskSession.tab);\n const [q,setQ]=useState(()=>adminDeskSession.q);\n const [searched,setSearched]=useState(()=>adminDeskSession.searched);\n const [detail,setDetail]=useState<AdminDetail>(()=>adminDeskSession.detail);\n const result=useMemo<"shen"|"liang"|"lin"|"third"|null>(()=>{if(!searched)return null;const t=q.trim();if(/候鸟第七年|沈妍|0712-4471/.test(t))return "shen";if(/迟迟|梁茵|0419-2286/.test(t))return "liang";if(/林楠|LN-2004-0718/.test(t))return "lin";if(/19-07|候舍/.test(t))return "third";return null},[searched,q]);\n useEffect(()=>{adminDeskSession.tab=tab;adminDeskSession.q=q;adminDeskSession.searched=searched;adminDeskSession.detail=detail},[tab,q,searched,detail]);\n useEffect(()=>{const timer=window.setTimeout(()=>{if(triggerAdminWechatBeat("shen-record"))onWechatIncoming?.()},900);return ()=>window.clearTimeout(timer)},[]);\n const fireShenBeat=()=>{if(triggerAdminWechatBeat("shen-record"))onWechatIncoming?.()};\n const doSearch=(e?:FormEvent)=>{e?.preventDefault();setSearched(true);setDetail(null);if(/候鸟第七年|沈妍|0712-4471/.test(q.trim()))fireShenBeat()};\n const openKnown=(name:string)=>{setQ(name);setSearched(true);setDetail(null);setTab("users");if(/候鸟第七年|沈妍/.test(name))fireShenBeat()};\n const openDetail=(next:AdminDetail)=>{setDetail(next);setTab("users")};\n return <main style={s.adminPage}>\n  <header style={s.adminHead}><div><i>烛</i><span><b>烛阴旧闻</b><small>旧档管理</small></span></div><span style={s.adminAccount}>旧档员-03</span></header>\n  <div style={s.adminLayout}>\n   <aside style={s.adminSide}><button className={tab==="watch"?"active":""} onClick={()=>{setTab("watch");setDetail(null)}}>观察名单</button><button className={tab==="users"?"active":""} onClick={()=>setTab("users")}>用户查询</button><button className={tab==="ops"?"active":""} onClick={()=>{setTab("ops");setDetail(null)}}>操作记录</button><button className={tab==="recycle"?"active":""} onClick={()=>{setTab("recycle");setDetail(null)}}>删除记录</button></aside>\n   <section style={s.adminBody}>\n    {tab==="watch"&&<WatchList openKnown={openKnown} onCopyMaterial={onCopyMaterial} hasMaterial={hasMaterial}/>} \n    {tab==="users"&&(detail?<AdminDetailPage detail={detail} openDetail={openDetail} onCopyMaterial={onCopyMaterial} hasMaterial={hasMaterial}/>:<><h2>用户查询</h2><form onSubmit={doSearch} style={s.adminSearch}><Search size={16}/><input value={q} onChange={e=>{setQ(e.target.value);setSearched(false);setDetail(null)}} placeholder="用户名 / UID / 关联姓名"/><button>查询</button></form>{searched&&!result&&<p style={s.adminEmpty}>没有匹配用户。</p>}{result==="shen"&&<ShenRecord openDetail={openDetail} onCopyMaterial={onCopyMaterial} hasMaterial={hasMaterial}/>} {result==="liang"&&<LiangRecord onCopyMaterial={onCopyMaterial} hasMaterial={hasMaterial}/>} {result==="lin"&&<LinRecord openDetail={openDetail}/>} {result==="third"&&<ThirdRecord onCopyMaterial={onCopyMaterial} hasMaterial={hasMaterial}/>}</>)}\n    {tab==="ops"&&<Operations/>}\n    {tab==="recycle"&&<Recycle/>}\n   </section>\n  </div>\n </main>;\n}'''
s,n=re.subn(r'function AdminDesk\(.*?\n\}\n\nconst watchRows=',admin_desk+'\n\nconst watchRows=',s,count=1,flags=re.S)
assert n==1

records='''function PortraitCard({src,label}:{src:string;label:string}){return <figure style={{margin:0,width:150,padding:7,border:"1px solid #c7c2b8",background:"#e9e3d7",boxShadow:"0 7px 20px #0002"}}><img src={src} alt="" style={{display:"block",width:"100%",aspectRatio:"4 / 5",objectFit:"cover",filter:"contrast(1.03) saturate(.88)"}}/><figcaption style={{padding:"7px 2px 1px",fontSize:10,color:"#67645e",letterSpacing:".04em"}}>{label}</figcaption></figure>}\nfunction PortraitPair({children}:{children:React.ReactNode}){return <div style={{display:"flex",gap:14,flexWrap:"wrap",padding:"12px 0 16px",alignItems:"flex-start"}}>{children}</div>}\nfunction DetailLink({children,onClick}:{children:React.ReactNode;onClick:()=>void}){return <button onClick={onClick} style={{width:"100%",margin:"8px 0 0",padding:"10px 12px",border:"1px solid #bdc5c0",borderRadius:6,background:"#f8faf8",color:"#33483f",textAlign:"left",fontSize:12,cursor:"pointer"}}>{children}</button>}\n\nfunction ShenRecord({openDetail,onCopyMaterial,hasMaterial}:{openDetail:(x:AdminDetail)=>void;onCopyMaterial?:(m:SharedMaterial)=>void;hasMaterial?:(id:string)=>boolean}){return <article style={s.userRecord}>\n <header style={s.userHead}><i>候</i><span><h3>候鸟第七年</h3><small>实名关联：沈妍 · UID 0712-4471 · 最后活动 2026-10-16 19:48</small></span><em>已控制</em></header>\n <PortraitPair><PortraitCard src={adultShen} label="当前档案影像"/></PortraitPair>\n <AddMaterialButton material={adminShenMaterial} onCopyMaterial={onCopyMaterial} hasMaterial={hasMaterial}/>\n <div style={s.statusGrid}><span><small>对契匹配</small><b>92%</b></span><span><small>血样</small><b>已采集</b></span><span><small>当前状态</small><b>已控制</b></span><span><small>执行批次</small><b>HN-1016-02</b></span></div>\n <section style={s.adminPanel}><h4>关联信息</h4><Record date="旧案" title="2004-07-17" meta="年龄 9 · 失踪 13 天" text="关联旧案：LN-2004-0718；关联对象：林楠。"/><DetailLink onClick={()=>openDetail("pair2004")}>查看旧案 LN-2004-0718</DetailLink><Record date="首次录入" title="2021-06-14" meta="自动索引匹配" text="论坛实名映射完成；进入长期观察。"/></section>\n <section style={s.adminPanel}><h4>观察记录</h4><Record date="2022-11-03 01:17" title="站内搜索记录" meta="候鸟第七年" text="查询：小时候走失 / 记不得 / 回来以后。"/><Record date="2024-09-07 00:46" title="旧厂区内容访问" meta="行为记录" text="连续查看岚棉三厂旧址照片 37 分钟。"/><Record date="2026-06-19 03:12" title="内容命中" meta="梦境帖" text="红铁皮盒、蓝窗帘、厨房位置重复出现。"/><Record date="2026-08-22 04:12" title="观察等级调整" meta="操作人：照骨" text="II → III；对契匹配 92%；恢复旧案关联观察。"/><Record date="2026-10-16 19:49" title="线下转交" meta="执行：旧档员-03" text="完成。停止公开区接触。"/><Record date="2026-10-16 20:52" title="样本登记" meta="内部任务" text="血样 2 管；保存状态：有效。"/><Record date="2026-10-16 21:06" title="人员状态变更" meta="旧档员-03" text="观察中 → 已控制。"/></section>\n <section style={s.adminPanel}><h4>执行信息</h4><Record date="HN-1016-02" title="对象类型：返契祭品" meta="执行批次" text="执行条件：待复核；当前场地字段未展开。"/></section>\n </article>}\n\nfunction AdminDetailPage({detail,openDetail,onCopyMaterial,hasMaterial}:{detail:Exclude<AdminDetail,null>;openDetail:(x:AdminDetail)=>void;onCopyMaterial?:(m:SharedMaterial)=>void;hasMaterial?:(id:string)=>boolean}){\n if(detail==="pair2004")return <Pair2004 openDetail={openDetail} onCopyMaterial={onCopyMaterial} hasMaterial={hasMaterial}/>;\n if(detail==="lin")return <LinRecord openDetail={openDetail}/>;\n if(detail==="reswap")return <ReswapRecord openDetail={openDetail} onCopyMaterial={onCopyMaterial} hasMaterial={hasMaterial}/>;\n if(detail==="third")return <ThirdRecord onCopyMaterial={onCopyMaterial} hasMaterial={hasMaterial}/>;\n return <SyncRecord onCopyMaterial={onCopyMaterial} hasMaterial={hasMaterial}/>;\n}\n\nfunction Pair2004({openDetail,onCopyMaterial,hasMaterial}:{openDetail:(x:AdminDetail)=>void;onCopyMaterial?:(m:SharedMaterial)=>void;hasMaterial?:(id:string)=>boolean}){return <article style={s.userRecord}>\n <h2 style={{marginTop:0}}>LN-2004-0718</h2><p style={{color:"#737872",fontSize:12}}>2004年旧案 · 双向易舍记录</p>\n <PortraitPair><PortraitCard src={childShen} label="沈妍 · 2004"/><PortraitCard src={childLin} label="林楠 · 2004"/></PortraitPair>\n <AddMaterialButton material={adminPair2004Material} onCopyMaterial={onCopyMaterial} hasMaterial={hasMaterial}/>\n <section style={s.adminPanel}><h4>执行记录</h4><Record date="A" title="舍：沈妍" meta="客源：林楠" text="易舍完成；返家后持续观察。"/><Record date="B" title="舍：林楠" meta="客源：沈妍" text="易舍完成；返家后持续观察。"/><Record date="结果" title="双向完成" meta="2004-07" text="两侧生命体征稳定；后续身份适应记录正常。"/></section>\n <DetailLink onClick={()=>openDetail("lin")}>查看关联对象：林楠</DetailLink>\n </article>}\n\nfunction LinRecord({openDetail}:{openDetail:(x:AdminDetail)=>void}){return <article style={s.userRecord}>\n <header style={s.userHead}><i>林</i><span><h3>林楠</h3><small>关联旧案：LN-2004-0718 · B侧</small></span><em>在册</em></header>\n <PortraitPair><PortraitCard src={adultLin} label="当前档案影像"/></PortraitPair>\n <div style={s.statusGrid}><span><small>旧案</small><b>2004</b></span><span><small>长期状态</small><b>稳定</b></span><span><small>近期执行</small><b>1</b></span><span><small>最后处理</small><b>10-12</b></span></div>\n <section style={s.adminPanel}><h4>关联记录</h4><Record date="2004-07" title="双向易舍" meta="LN-2004-0718" text="B侧长期观察；稳定期 22 年。"/><Record date="2026-10-12" title="执行记录" meta="记录 1 条" text="状态：完成。"/><DetailLink onClick={()=>openDetail("reswap")}>查看 2026-10-12 执行记录</DetailLink></section>\n </article>}\n\nfunction ReswapRecord({openDetail,onCopyMaterial,hasMaterial}:{openDetail:(x:AdminDetail)=>void;onCopyMaterial?:(m:SharedMaterial)=>void;hasMaterial?:(id:string)=>boolean}){return <article style={s.userRecord}>\n <h2 style={{marginTop:0}}>2026-10-12 · 再舍验证</h2><p style={{color:"#737872",fontSize:12}}>B侧长期样本 / 候舍对象 19-07</p>\n <PortraitPair><PortraitCard src={adultLin} label="B侧 · 林楠登记身体"/><PortraitCard src={adultThird} label="候舍对象 19-07"/></PortraitPair>\n <AddMaterialButton material={adminReswapMaterial} onCopyMaterial={onCopyMaterial} hasMaterial={hasMaterial}/>\n <section style={s.adminPanel}><h4>试验信息</h4><Record date="类型" title="再舍验证" meta="RS-2026-1012" text="验证已完成一次长期易舍的客，在第二次更换舍后能否保持记忆连续与主体稳定。"/><Record date="选择" title="B侧旧客" meta="稳定期 22 年" text="2004年易舍后长期稳定；作为连续易舍样本。候舍对象 19-07：自愿，匹配通过。"/><Record date="结果" title="执行完成" meta="2026-10-12 22:13" text="两侧生命体征稳定；原对契 0712-4471 出现同步异常。"/></section>\n <DetailLink onClick={()=>openDetail("third")}>查看候舍对象 19-07</DetailLink><DetailLink onClick={()=>openDetail("sync")}>查看关联异常：0712-4471</DetailLink>\n </article>}\n\nfunction ThirdRecord({onCopyMaterial,hasMaterial}:{onCopyMaterial?:(m:SharedMaterial)=>void;hasMaterial?:(id:string)=>boolean}){return <article style={s.userRecord}>\n <header style={s.userHead}><i>19</i><span><h3>候舍对象 19-07</h3><small>成人候舍库 · 自愿对象</small></span><em>隔离</em></header>\n <PortraitPair><PortraitCard src={adultThird} label="当前档案影像"/></PortraitPair>\n <AddMaterialButton material={adminThirdMaterial} onCopyMaterial={onCopyMaterial} hasMaterial={hasMaterial}/>\n <section style={s.adminPanel}><h4>执行后观察</h4><Record date="10-12 22:36" title="身份陈述异常" meta="连续 4 次" text="对象否认登记身份，反复陈述：‘我叫沈妍。’"/><Record date="10-12 23:02" title="环境识别异常" meta="问询记录" text="声称住所不在当前登记地址；要求联系徐宁。"/><Record date="当前" title="状态：隔离" meta="暂停外部接触" text="等待后续身份稳定评估。"/></section>\n </article>}\n\nfunction SyncRecord({onCopyMaterial,hasMaterial}:{onCopyMaterial?:(m:SharedMaterial)=>void;hasMaterial?:(id:string)=>boolean}){return <article style={s.userRecord}>\n <h2 style={{marginTop:0}}>0712-4471 · 关联同步异常</h2>\n <PortraitPair><PortraitCard src={adultShen} label="关联对象：沈妍"/></PortraitPair>\n <AddMaterialButton material={adminSyncMaterial} onCopyMaterial={onCopyMaterial} hasMaterial={hasMaterial}/>\n <section style={s.adminPanel}><h4>异常记录</h4><Record date="起点" title="2026-10-12 23:04" meta="B侧再次易舍后 51 分钟" text="原对契同步值异常升高。"/><Record date="表现" title="记忆回流" meta="0712-4471" text="非本人童年场景描述增加；林楠旧址识别反应；对‘楠楠’称呼持续反应。"/><Record date="处置理由" title="控制旧对契另一端" meta="执行 HN-1016-02" text="同步反应持续升高，可能影响二次易舍稳定性。转入控制，保留作旧对契稳定评估。"/><Record date="当前" title="已控制" meta="HN-1016-02" text="线下转交完成；样本已登记；等待下一步。"/></section>\n </article>}\n\nfunction LiangRecord'''
s,n=re.subn(r'function ShenRecord\(.*?\nfunction LiangRecord',records,s,count=1,flags=re.S)
assert n==1

s=s.replace('function Operations(){return <><h2>操作记录</h2><div style={s.adminPanel}>','function Operations(){return <><h2>操作记录</h2><div style={s.adminPanel}><Record date="2026-10-17 18:51" title="访问异常复核：0712-4471" meta="来源：折柳" text="确认访问者为徐宁。暂不处理。"/>',1)

